							</div>
						</dl>
					</section>

					<!-- Rekening & Pajak -->
					<section
						class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
					>
						<h2
							class="mb-3 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
						>
							Rekening & Pajak
						</h2>
						<dl class="grid grid-cols-2 gap-3">
							<div>
								<dt class="text-sm text-ui-ink-gray-500">Nama Bank</dt>
								<dd class="font-medium text-ui-ink-gray-900">
									{{ data.nama_bank || '—' }}
								</dd>
							</div>
							<div>
								<dt class="text-sm text-ui-ink-gray-500">Nomor Rekening</dt>
								<dd class="break-all font-medium text-ui-ink-gray-900">
									{{ data.nomor_rekening || '—' }}
								</dd>
							</div>
							<div>
								<dt class="text-sm text-ui-ink-gray-500">Tax Code</dt>
								<dd class="font-medium text-ui-ink-gray-900">
									{{ data.tax_code || '—' }}
								</dd>
							</div>
							<div>
								<dt class="text-sm text-ui-ink-gray-500">Tax Rate</dt>
								<dd class="font-medium text-ui-ink-gray-900">
									{{ data.tax_rate ? `${data.tax_rate}%` : '—' }}
								</dd>
							</div>
						</dl>
					</section>

					<!-- Dokumen -->
					<section
						class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
					>
						<h2
							class="mb-3 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
						>
							Dokumen
						</h2>
						<button
							v-if="data.file_dokumen"
							type="button"
							class="flex w-full items-center gap-3 rounded-xl border border-ui-line-gray-200 p-3 text-left transition hover:bg-ui-surface-gray-50 active:bg-ui-surface-gray-100"
							@click="bukaPdf"
						>
							<span
								class="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-ui-surface-red-100 text-xs font-bold text-ui-ink-red-700"
								>PDF</span
							>
							<span class="min-w-0 flex-1">
								<span class="block truncate font-medium text-ui-ink-gray-900">{{
									namaFile(data.file_dokumen)
								}}</span>
								<span class="text-sm text-ui-ink-gray-500"
									>Ketuk untuk melihat</span
								>
							</span>
						</button>
						<p v-else class="text-ui-ink-gray-500">—</p>
					</section>

					<!-- Pengajuan -->
					<section
						class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
					>
						<h2
							class="mb-3 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
						>
							Pengajuan
						</h2>
						<dl class="grid grid-cols-2 gap-3">
							<div class="col-span-2">
								<dt class="text-sm text-ui-ink-gray-500">Diajukan Oleh</dt>
								<dd class="font-medium text-ui-ink-gray-900">
									{{ data.nama_pengaju || data.diajukan_oleh || '—' }}
									<span
										v-if="data.peran_pengaju"
										class="font-normal text-ui-ink-gray-500"
										>({{ data.peran_pengaju }})</span
									>
								</dd>
							</div>
							<div>
								<dt class="text-sm text-ui-ink-gray-500">Cabang</dt>
								<dd class="font-medium text-ui-ink-gray-900">
									{{ data.cabang || '—' }}
								</dd>
							</div>
							<div>
								<dt class="text-sm text-ui-ink-gray-500">Tanggal Pengajuan</dt>
								<dd class="font-medium text-ui-ink-gray-900">
									{{ formatTanggal(data.tanggal_pengajuan) }}
								</dd>
							</div>
							<div v-if="data.data_mokas" class="col-span-2">
								<dt class="text-sm text-ui-ink-gray-500">Data Mokas</dt>
								<dd class="font-medium text-ui-ink-green-700">
									Sudah dibuat ({{ data.data_mokas }})
								</dd>
							</div>
						</dl>
					</section>

					<!-- Riwayat Approval -->
					<section
						v-if="riwayat.length"
						class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
					>
						<h2
							class="mb-3 text-sm font-semibold uppercase tracking-wide text-ui-ink-gray-400"
						>
							Riwayat Approval
						</h2>
						<ol class="space-y-3">
							<li v-for="r in riwayat" :key="r.label" class="flex gap-3">
								<span
									class="mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full"
									:class="
										r.ditolak ? 'bg-ui-ink-red-600' : 'bg-ui-ink-green-600'
									"
								/>
								<div class="min-w-0">
									<p class="font-medium text-ui-ink-gray-900">{{ r.label }}</p>
									<p class="text-sm text-ui-ink-gray-500">
										{{ r.nama }} · {{ formatWaktu(r.waktu) }}
									</p>
								</div>
							</li>
						</ol>
					</section>
				</div>
			</div>
		</div>

		<!-- ============ AKSI WORKFLOW ============ -->
		<div
			v-if="data?.aksi?.length"
			class="fixed inset-x-0 bottom-0 z-30 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<div class="app-container-narrow flex gap-3">
				<button
					v-for="a in data.aksi"
					:key="a.action"
					type="button"
					:disabled="!!menjalankan"
					class="min-h-[44px] flex-1 rounded-lg px-4 py-2 text-base font-semibold transition disabled:opacity-50"
					:class="kelasTombol(a.action)"
					@click="mintaKonfirmasi(a.action)"
				>
					{{ menjalankan === a.action ? 'Memproses…' : a.action }}
				</button>
			</div>
		</div>

		<!-- ============ DIALOG KONFIRMASI ============ -->
		<div
			v-if="konfirmasi.aksi"
			class="fixed inset-0 z-50 flex items-end justify-center bg-black/40 p-4 sm:items-center"
			@click.self="tutupKonfirmasi"
		>
			<div class="w-full max-w-md rounded-2xl bg-ui-surface p-5 shadow-xl">
				<h3 class="mb-2 text-lg font-semibold text-ui-ink-gray-900">Konfirmasi</h3>
				<p class="mb-5 text-base text-ui-ink-gray-700">{{ konfirmasi.pesan }}</p>
				<div class="flex gap-3">
					<button
						type="button"
						class="min-h-[44px] flex-1 rounded-lg border border-ui-line-gray-300 bg-ui-surface px-4 py-2 font-medium text-ui-ink-gray-700"
						@click="tutupKonfirmasi"
					>
						Batal
					</button>
					<button
						type="button"
						class="min-h-[44px] flex-1 rounded-lg px-4 py-2 font-semibold"
						:class="kelasTombol(konfirmasi.aksi)"
						@click="jalankan"
					>
						Ya, {{ konfirmasi.aksi }}
					</button>
				</div>
			</div>
		</div>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { mokasPillClass, pesanKonfirmasi } from '../data/requestMokasStatus'
import { notifyError, notifySuccess } from '../composables/toast'
import { openPdf } from '../composables/pdfViewer'
import { useBackNavigation } from '../composables/useBackNavigation'

const API = '/api/method/juragan.api.portal.request_mokas'

const route = useRoute()
const { backTarget, backLabel } = useBackNavigation({ name: 'RequestMokas' }, 'Request Mokas')
const name = computed(() => route.params.name)

const data = ref(null)
const loading = ref(false)
const error = ref('')
const menjalankan = ref('')
const konfirmasi = reactive({ aksi: '', pesan: '' })

function pesanError(json, res) {
	try {
		if (json && json._server_messages) {
			return JSON.parse(json._server_messages)
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* abaikan */
	}
	return (json && (json.exception || json.message)) || `HTTP ${res.status}`
}

async function muat() {
	loading.value = true
	error.value = ''
	try {
		const params = new URLSearchParams({ name: name.value })
		const res = await fetch(`${API}.get_detail?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(pesanError(json, res))
		data.value = json.message
	} catch (e) {
		error.value = e.message || String(e)
	} finally {
		loading.value = false
	}
}

const dataMokas = computed(() => {
	const d = data.value || {}
	const baris = [
		{ label: 'Nama Broker / Mokas', value: d.nama_mokas },
		{ label: 'Kode Broker', value: d.kode_mokas },
		{ label: 'Tipe Broker', value: d.tipe_broker },
	]
	if (d.tipe_broker === 'Mokas')
		baris.push({ label: 'Internal', value: d.internal ? 'Ya' : 'Tidak' })
	baris.push(
		{ label: 'Nama Sesuai KTP', value: d.nama_pemilik },
		{ label: 'NIK', value: d.nik },
		{ label: 'No HP', value: d.no_hp },
		{ label: 'Alamat', value: d.alamat_mokas }
	)
	return baris
})

const riwayat = computed(() => {
	const d = data.value || {}
	const r = []
	if (d.disetujui_pincab_oleh)
		r.push({
			label: 'Direkomendasi Pimcab',
			nama: d.disetujui_pincab_oleh_nama,
			waktu: d.waktu_approval_pincab,
		})
	if (d.disetujui_mo_oleh)
		r.push({
			label: 'Disetujui MO',
			nama: d.disetujui_mo_oleh_nama,
			waktu: d.waktu_approval_mo,
		})
	if (d.disetujui_direktur_oleh)
		r.push({
			label: 'Disetujui Direktur',
			nama: d.disetujui_direktur_oleh_nama,
			waktu: d.waktu_approval_direktur,
		})
	if (d.ditolak_oleh)
		r.push({
			label: 'Ditolak',
			nama: d.ditolak_oleh_nama,
			waktu: d.waktu_ditolak,
			ditolak: true,
		})
	return r
})

function kelasTombol(aksi) {
	if (aksi === 'Reject') return 'bg-ui-surface-red-600 text-white hover:bg-ui-surface-red-700'
	return 'bg-primary text-ui-onPrimary hover:bg-primary/90'
}

function mintaKonfirmasi(aksi) {
	konfirmasi.aksi = aksi
	konfirmasi.pesan = pesanKonfirmasi(aksi, data.value?.status)
}
function tutupKonfirmasi() {
	konfirmasi.aksi = ''
	konfirmasi.pesan = ''
}

async function jalankan() {
	const aksi = konfirmasi.aksi
	tutupKonfirmasi()
	menjalankan.value = aksi
	try {
		const res = await fetch(`${API}.jalankan_aksi`, {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ name: name.value, action: aksi }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(pesanError(json, res))
		data.value = json.message
		const status = data.value?.status
		if (aksi === 'Reject') notifySuccess(`Request ${name.value} ditolak.`)
		else if (status === 'Approved')
			notifySuccess(`Request ${name.value} di-approve. Data Mokas sudah dibuat.`)
		else if (aksi === 'Ajukan Approval')
			notifySuccess(`Request ${name.value} diajukan. Status: ${status}`)
		else notifySuccess(`Request ${name.value} di-approve. Status: ${status}`)
	} catch (e) {
		notifyError(e, `Gagal menjalankan "${aksi}"`)
	} finally {
		menjalankan.value = ''
	}
}

function bukaPdf() {
	openPdf(data.value.file_dokumen, `Dokumen ${name.value}`)
}

function namaFile(url) {
	return String(url || '')
		.split('/')
		.pop()
}
function formatTanggal(v) {
	if (!v) return '—'
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}
function formatWaktu(v) {
	if (!v) return '—'
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleString('id-ID', {
		day: '2-digit',
		month: 'short',
		year: 'numeric',
		hour: '2-digit',
		minute: '2-digit',
	})
}

onMounted(async () => {
	await refreshCsrfToken()
	muat()
})
</script>
